package com.docgen.service

import java.net.{URI, URL}
import java.nio.file.{Files, Path, Paths}
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

// Multi-tenant PDF generation service with resource resolution
object TenantConfig {
  private val tenantDomains: mutable.Map[String, Set[String]] = mutable.Map(
    "tenant-a" -> Set("assets.tenant-a.com", "cdn.tenant-a.com"),
    "tenant-b" -> Set("assets.tenant-b.com", "static.tenant-b.com"),
    "shared" -> Set("shared-assets.docgen.internal")
  )

  def getAllowedDomains(tenantId: String): Set[String] = {
    tenantDomains.getOrElse(tenantId, Set.empty) ++ tenantDomains.getOrElse("shared", Set.empty)
  }

  def registerTenant(tenantId: String, domains: Set[String]): Unit = {
    tenantDomains(tenantId) = domains
  }
}

case class ResourceRef(uri: String, tenantId: String, refType: String)

trait ResourceResolver {
  def resolve(ref: ResourceRef): Either[String, ResolvedResource]
}

case class ResolvedResource(finalUrl: String, contentType: String, tenantId: String)

// Validates that resource URIs belong to the tenant's allowed domains
class TenantIsolatedResolver extends ResourceResolver {

  private def normalizeHost(host: String): String = {
    // Strip port and normalize
    val h = host.toLowerCase.trim
    if (h.contains(":")) h.substring(0, h.indexOf(':')) else h
  }

  private def isAllowedScheme(scheme: String): Boolean = {
    val s = Option(scheme).map(_.toLowerCase).getOrElse("")
    s == "https" || s == "http"
  }

  private def validateDomainIsolation(uri: URI, tenantId: String): Boolean = {
    val host = Option(uri.getHost).map(normalizeHost).getOrElse("")
    val allowedDomains = TenantConfig.getAllowedDomains(tenantId)
    allowedDomains.exists(domain => host == domain || host.endsWith("." + domain))
  }

  // Handles relative references by resolving against tenant base
  private def resolveRelative(ref: ResourceRef): URI = {
    val baseUri = new URI(s"https://assets.${ref.tenantId}.com/resources/")
    baseUri.resolve(ref.uri)
  }

  override def resolve(ref: ResourceRef): Either[String, ResolvedResource] = {
    val uri = Try(new URI(ref.uri)) match {
      case Success(u) if u.isAbsolute => u
      case Success(u) => resolveRelative(ref)
      case Failure(e) => return Left(s"Invalid URI: ${e.getMessage}")
    }

    if (!isAllowedScheme(uri.getScheme)) {
      return Left(s"Disallowed scheme: ${uri.getScheme}")
    }

    if (!validateDomainIsolation(uri, ref.tenantId)) {
      return Left(s"Domain not allowed for tenant ${ref.tenantId}")
    }

    Right(ResolvedResource(
      finalUrl = uri.toString,
      contentType = inferContentType(ref.refType),
      tenantId = ref.tenantId
    ))
  }

  private def inferContentType(refType: String): String = refType match {
    case "image" => "image/png"
    case "stylesheet" => "text/css"
    case "font" => "font/woff2"
    case _ => "application/octet-stream"
  }
}

// PDF template engine that processes resource references
class PdfTemplateEngine(resolver: ResourceResolver) {

  case class TemplateDirective(action: String, target: String, params: Map[String, String])

  // Upper bound on redirect chain depth to prevent resource-exhaustion via excessive recursion
  private val MaxRedirectDepth = 10

  def processTemplate(template: String, tenantId: String): Either[String, List[ResolvedResource]] = {
    val directives = parseDirectives(template)
    val results = directives.map { directive =>
      directive.action match {
        case "include" => resolveInclude(directive, tenantId)
        case "redirect" => resolveRedirect(directive, tenantId)
        case "embed" => resolveEmbed(directive, tenantId)
        case _ => Left(s"Unknown directive: ${directive.action}")
      }
    }

    val errors = results.collect { case Left(e) => e }
    if (errors.nonEmpty) Left(errors.mkString("; "))
    else Right(results.collect { case Right(r) => r })
  }

  private def resolveInclude(directive: TemplateDirective, tenantId: String): Either[String, ResolvedResource] = {
    resolver.resolve(ResourceRef(directive.target, tenantId, "stylesheet"))
  }

  // The redirect directive resolves a chain of URLs for link generation in PDFs
  private def resolveRedirect(directive: TemplateDirective, tenantId: String): Either[String, ResolvedResource] = {
    // Safely parse and bound the depth parameter to avoid NumberFormatException (DoS)
    // and excessive-recursion resource exhaustion.
    val rawDepth = Try(directive.params.getOrElse("depth", "1").trim.toInt).getOrElse(1)
    val chainDepth =
      if (rawDepth < 0) 0
      else if (rawDepth > MaxRedirectDepth) MaxRedirectDepth
      else rawDepth
    val finalTarget = followRedirectChain(directive.target, tenantId, chainDepth)
    finalTarget
  }

  private def followRedirectChain(target: String, tenantId: String, depth: Int): Either[String, ResolvedResource] = {
    if (depth <= 0) {
      // Terminal resolution - must still validate the final target
      resolver.resolve(ResourceRef(target, tenantId, "redirect"))
    } else {
      // Validate current hop
      resolver.resolve(ResourceRef(target, tenantId, "redirect")) match {
        case Right(resolved) =>
          // Extract next hop from params (simulating HTTP redirect following)
          val nextTarget = extractNextHop(resolved.finalUrl)
          followRedirectChain(nextTarget, tenantId, depth - 1)
        case Left(err) => Left(err)
      }
    }
  }

  // Simulates extracting Location header from redirect response
  // In production this would do an HTTP HEAD request
  private def extractNextHop(currentUrl: String): String = {
    // The "next hop" is derived from a query parameter in the URL
    // This simulates following server-side redirects during PDF link resolution
    Try(new URI(currentUrl)) match {
      case Success(uri) =>
        val query = Option(uri.getQuery).getOrElse("")
        val params = query.split("&").map(_.split("=", 2)).collect {
          case Array(k, v) => k -> java.net.URLDecoder.decode(v, "UTF-8")
        }.toMap
        params.getOrElse("next", currentUrl)
      case Failure(_) => currentUrl
    }
  }

  private def resolveEmbed(directive: TemplateDirective, tenantId: String): Either[String, ResolvedResource] = {
    resolver.resolve(ResourceRef(directive.target, tenantId, "image"))
  }

  private def parseDirectives(template: String): List[TemplateDirective] = {
    val pattern = """\{\{(\w+)\s+"([^"]+)"(\s+\{([^}]*)\})?\}\}""".r
    pattern.findAllMatchIn(template).map { m =>
      val params = Option(m.group(4)).map { paramStr =>
        paramStr.split(",").map(_.split(":", 2)).collect {
          case Array(k, v) => k.trim -> v.trim
        }.toMap
      }.getOrElse(Map.empty)
      TemplateDirective(m.group(1), m.group(2), params)
    }.toList
  }
}

// Entry point for PDF generation requests
object PdfGenerationService {
  private val resolver = new TenantIsolatedResolver()
  private val engine = new PdfTemplateEngine(resolver)

  def generatePdf(tenantId: String, templateContent: String): Either[String, String] = {
    if (tenantId == null || tenantId.isEmpty) {
      return Left("Tenant ID required")
    }

    engine.processTemplate(templateContent, tenantId) match {
      case Right(resources) =>
        // In real implementation, would fetch resources and render PDF
        Right(s"PDF generated with ${resources.size} resources for tenant $tenantId")
      case Left(error) =>
        Left(s"Template processing failed: $error")
    }
  }
}
